'use strict';

// Extractor uses one pinned, portable LSTM core on every supported PC.
let core;
module.exports = async (_oem, _options, res) => {
  if (!core) {
    res.progress({ status: 'loading Extractor OCR core', progress: 0 });
    core = require('tesseract.js-core/tesseract-core-lstm');
    res.progress({ status: 'loading Extractor OCR core', progress: 1 });
  }
  return core;
};
